contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters to drive behavior
    function run(address possibleNewOwner) public payable {
        require(true);

        // Read the owner before any calls
        address ownerBefore = c.owner();

        // Try calling owned() and record whether it reverts
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // Try transferOwnership to possibleNewOwner and record whether it reverts
        bool transferReverted;
        try c.transferOwnership(possibleNewOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // Read owner after attempts
        address ownerAfter = c.owner();

        // General rule asserted:
        // - If transferOwnership did not revert, ownerAfter must equal possibleNewOwner.
        // - If transferOwnership reverted, ownerAfter must equal ownerBefore (no change).
        // - Additionally, if owned() succeeded then the caller was the ownerBefore; if it reverted then caller was not the ownerBefore.
        assert(
            (transferReverted ? (ownerAfter == ownerBefore) : (ownerAfter == possibleNewOwner))
            && (ownedReverted ? (ownerBefore != address(this)) : (ownerBefore == address(this)))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function driving the contract with one parameter
    function run(address newOwner) public payable {
        require(newOwner != address(0)); // reasonable precondition but not about c's state

        // Read owner before any state-changing calls
        address ownerBefore = c.owner();

        // Attempt transferOwnership and record whether it reverted
        bool transferReverted;
        try c.transferOwnership(newOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // Read owner after the attempt
        address ownerAfter = c.owner();

        // General rule: successful transfer sets owner to newOwner; reverted transfer leaves owner unchanged
        assert(transferReverted ? (ownerAfter == ownerBefore) : (ownerAfter == newOwner));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the contract
    function run(address maybeNew) public payable {
        // no precondition on c's state; only require a valid address param to avoid trivial nonsense
        require(maybeNew != address(0));

        // read owner before any state-changing calls
        address ownerBefore = c.owner();

        // Attempt to call transferOwnership with maybeNew, record whether it reverted
        bool transferReverted;
        try c.transferOwnership(maybeNew) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // Read owner after the attempt
        address ownerAfter = c.owner();

        // General rule: If the call reverted, owner must remain unchanged. If it succeeded, then
        // because msg.sender inside C is this test contract, the new owner must be this contract.
        assert(transferReverted ? (ownerAfter == ownerBefore) : (ownerAfter == address(this)));
    }

    receive() external payable {}
}
